import { Controller, Get, Patch, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const INSURANCE_TYPES = ['국민연금', '건강보험', '고용보험'];

const FROM_WHERE = `
  FROM social_insurance_deduction d
  JOIN employee e ON e.employee_id = d.employee_id
  WHERE d.attribution_month = :month
    AND d.insurance_type = :type
    AND (CAST(:employeeId AS bigint) IS NULL OR d.employee_id = CAST(:employeeId AS bigint))
    AND (CAST(:departmentId AS bigint) IS NULL OR e.department_id = CAST(:departmentId AS bigint))
`;

function optionalId(value: unknown): string | null {
  if (value === undefined || value === null || value === '') {
    return null;
  }
  const text = String(value);
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 조건 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr02203Controller {
  @Get('/social-insurance-deductions')
  async listSocialInsuranceDeductions(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '인사 담당자');
    const query = checks.queryOf(req.query);
    const month = String(query['attributionMonth'] ?? '');
    const type = String(query['insuranceType'] ?? '');
    if (!/^\d{6}$/.test(month)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '귀속연월을 YYYYMM 형식으로 입력하세요.');
    }
    if (!INSURANCE_TYPES.includes(type)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '보험 종류를 선택하세요.');
    }
    const employeeId = optionalId(query['employeeId']);
    const departmentId = optionalId(query['departmentId']);
    const pageText = String(query['page'] ?? '0');
    const sizeText = String(query['size'] ?? '20');
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호나 크기 형식이 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), 200);
    return transaction(async (db) => {
      const filter = { month, type, employeeId, departmentId };
      const sums = await db.query(
        `SELECT COUNT(*) AS "total",
                COALESCE(SUM(COALESCE(d.adjusted_amount, d.calculated_amount)), 0) AS "sum"` + FROM_WHERE,
        filter,
      );
      const total = Number(sums[0]?.total ?? 0);
      const totalDeductionAmount = Number(sums[0]?.sum ?? 0);
      const rows = await db.query(
        `SELECT d.social_insurance_deduction_id AS "socialInsuranceDeductionId",
                d.employee_id AS "employeeId",
                d.grade AS "grade",
                d.calculated_amount AS "calculatedAmount",
                d.adjusted_amount AS "adjustedAmount",
                CASE
                  WHEN d.grade IS NULL THEN '등급 정보가 없어 산출할 수 없습니다.'
                  WHEN d.calculated_amount IS NULL AND d.adjusted_amount IS NULL THEN '급여 정보가 없어 산출할 수 없습니다.'
                  ELSE NULL
                END AS "errorReason"` +
          FROM_WHERE +
          ` ORDER BY d.employee_id, d.social_insurance_deduction_id
            LIMIT CAST(:size AS int) OFFSET CAST(:offset AS int)`,
        { ...filter, size, offset: page * size },
      );
      const items = rows.map((row: Record<string, unknown>) => ({
        socialInsuranceDeductionId: Number(row['socialInsuranceDeductionId']),
        employeeId: Number(row['employeeId']),
        grade: row['grade'] ?? null,
        calculatedAmount: row['calculatedAmount'] === null ? null : Number(row['calculatedAmount']),
        adjustedAmount: row['adjustedAmount'] === null ? null : Number(row['adjustedAmount']),
        errorReason: row['errorReason'] ?? null,
        totalDeductionAmount,
      }));
      return { items, page, size, total };
    });
  }

  @Patch('/social-insurance-deductions/:socialInsuranceDeductionId')
  async updateSocialInsuranceDeduction(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자', '인사 담당자');
    const id = req.params['socialInsuranceDeductionId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '공제내역 ID 형식이 올바르지 않습니다.');
    }
    const data = checks.inputOf(req.body);
    const raw = data['adjustedAmount'];
    if (raw === undefined || raw === null || raw === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '수정 공제금액을 입력하세요.');
    }
    const amount = typeof raw === 'number' ? raw : typeof raw === 'string' && raw.trim() !== '' ? Number(raw) : NaN;
    if (!Number.isFinite(amount) || amount < 0) {
      throw new ApiError(422, 'INVALID_DEDUCTION_AMOUNT', '공제금액은 0 이상의 숫자로 입력하세요.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT social_insurance_deduction_id AS "socialInsuranceDeductionId"
         FROM social_insurance_deduction
         WHERE social_insurance_deduction_id = CAST(:id AS bigint)`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'DEDUCTION_NOT_FOUND', '공제내역을 찾을 수 없습니다.');
      }
      // TODO(질문): 급여 마감 여부(PAYROLL_CLOSED)와 변경 이력은 입력 스키마에 근거 테이블이 없어 구현하지 못했다.
      const rows = await db.query(
        `UPDATE social_insurance_deduction
         SET adjusted_amount = CAST(:amount AS numeric), updated_at = now()
         WHERE social_insurance_deduction_id = CAST(:id AS bigint)
         RETURNING social_insurance_deduction_id AS "socialInsuranceDeductionId",
                   adjusted_amount AS "adjustedAmount"`,
        { id, amount },
      );
      return {
        socialInsuranceDeductionId: Number(rows[0]['socialInsuranceDeductionId']),
        adjustedAmount: Number(rows[0]['adjustedAmount']),
      };
    });
  }
}

