import { useState } from 'react';
import {
  Band,
  DataTable,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page as ListPage, PageProps, Row } from '../kit';

const SIZE = 20;
const TYPES: [string, string][] = [
  ['국민연금', '국민연금'],
  ['건강보험', '건강보험'],
  ['고용보험', '고용보험'],
];

export default function FnSfr02203Page({ role, notify }: PageProps) {
  const [month, setMonth] = useState('');
  const [type, setType] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);
  const [searchError, setSearchError] = useState('');
  const [editing, setEditing] = useState<Row | null>(null);
  const [amount, setAmount] = useState<number | string>('');

  const { data, error, reload } = useData<ListPage>(async () => {
    if (!applied) {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<ListPage>('GET', '/social-insurance-deductions', role, undefined, {
      ...applied,
      page: pageNo,
      size: SIZE,
    });
  }, [applied, pageNo, role]);

  const items = data?.items ?? [];
  const totalAmount = items.length > 0 ? items[0].totalDeductionAmount : 0;
  const errorCount = items.filter((row) => row.errorReason).length;

  const search = () => {
    if (!/^\d{6}$/.test(month)) {
      setSearchError('귀속연월을 YYYYMM 형식(예: 202501)으로 입력하세요.');
      return;
    }
    if (!type) {
      setSearchError('보험 종류를 선택하세요.');
      return;
    }
    setSearchError('');
    setPageNo(0);
    setApplied({ attributionMonth: month, insuranceType: type, employeeId, departmentId });
  };

  const reset = () => {
    setMonth('');
    setType('');
    setEmployeeId('');
    setDepartmentId('');
    setSearchError('');
    setPageNo(0);
    setApplied(null);
  };

  const openEdit = (row: Row) => {
    setEditing(row);
    setAmount((row.adjustedAmount ?? row.calculatedAmount ?? '') as number | string);
  };

  const save = async () => {
    if (!editing) {
      return;
    }
    if (amount === '') {
      throw new Error('수정 공제금액을 입력하세요.');
    }
    await call('PATCH', `/social-insurance-deductions/${editing.socialInsuranceDeductionId}`, role, {
      adjustedAmount: amount,
    });
    notify('공제 금액을 수정했습니다.');
    setEditing(null);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>공제 합계</h2>
        <Tiles
          items={[
            ['보험별 공제 합계', <Num value={totalAmount} />],
            ['조회 건수', <Num value={data?.total ?? 0} />],
            ['산출 불가', <Num value={errorCount} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>공제내역서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="귀속연월" required hint="YYYYMM">
            <TextInput value={month} onChange={setMonth} placeholder="202501" />
          </Field>
          <Field label="보험 종류" required>
            <Select value={type} onChange={setType} options={TYPES} />
          </Field>
          <Field label="임직원">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="주부서">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} />
          </Field>
        </Filters>
        {searchError ? <ErrorText text={searchError} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={data?.total ?? 0} />
        <DataTable
          rows={items}
          empty="귀속연월과 보험 종류를 선택해 조회하세요."
          onRowClick={openEdit}
          columns={[
            {
              key: 'employeeId',
              label: '임직원',
              render: (row) => <RefName table="employee" role={role} value={row.employeeId} />,
            },
            { key: 'grade', label: '적용 등급' },
            { key: 'calculatedAmount', label: '산출 공제금액', render: (row) => <Num value={row.calculatedAmount} /> },
            { key: 'adjustedAmount', label: '수정 공제금액', render: (row) => <Num value={row.adjustedAmount} /> },
            { key: 'errorReason', label: '산출 불가 사유' },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data?.total ?? 0} onPage={setPageNo} />
      </section>
      {editing ? (
        <Drawer title="공제 금액 수정" onClose={() => setEditing(null)}>
          <Pairs
            items={[
              ['임직원', <RefName table="employee" role={role} value={editing.employeeId} />],
              ['적용 등급', (editing.grade as string) ?? '-'],
              ['산출 공제금액', <Num value={editing.calculatedAmount} />],
              ['산출 불가 사유', (editing.errorReason as string) ?? '-'],
            ]}
          />
          <Form onSubmit={save} submit="저장">
            <Field label="수정 공제금액" required wide>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
